  TableHead,
  TableHeaderCell,
  TableRow,
} from "@/components/ui/table";
import { ANONYMOUS_FLAG_CONTEXT } from "@/hooks/flag-context";
import { useFormAction } from "@/hooks/use-form-action";
import { isEnabled } from "@/lib/feature-flags";
import type { UpdateNotificationPreferenceInput } from "@/schemas/notification";
import type { ActionResult } from "@/types/api";
import type { OrgId, UserId } from "@/types/common";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type {
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";
import type { ReactElement } from "react";

export type NotificationPreferencesFormProps = {
  orgId: OrgId;
  userId: UserId;
  preferences: readonly NotificationPreference[];
  flags: FeatureFlagSnapshot;
  onSubmit: (
    input: UpdateNotificationPreferenceInput,
  ) => Promise<ActionResult<NotificationPreference>>;
};

const KIND_LABELS: Readonly<Record<NotificationKind, string>> = {
  issue_assigned: "Issue assigned to me",
  issue_status_changed: "Issue status changed",
  issue_due_soon: "Issue due soon",
  issue_overdue: "Issue overdue",
  comment_created: "New comment",
  comment_mention: "I was mentioned",
  member_invited: "Member invited",
  member_joined: "Member joined",
  project_archived: "Project archived",
  plan_limit_reached: "Plan limit reached",
  digest_ready: "Daily digest ready",
};

export function NotificationPreferencesForm(
  props: NotificationPreferencesFormProps,
): ReactElement | null {
  const { orgId, userId, preferences, flags, onSubmit } = props;
  const { submit, pending } = useFormAction(onSubmit);

  const digestOn =
    flags.digest_email === true ||
    isEnabled("digest_email", ANONYMOUS_FLAG_CONTEXT);

  function update(
    preference: NotificationPreference,
    patch: Partial<
      Pick<NotificationPreference, "inApp" | "email" | "digestOnly">
    >,
  ): void {
    void submit({
      orgId,
      userId,
      kind: preference.kind,
      inApp: patch.inApp ?? preference.inApp,
      email: patch.email ?? preference.email,
      digestOnly: patch.digestOnly ?? preference.digestOnly,
    });
  }

/**
 * Presentation helpers for the audit trail.
 *
 * `ActivityEvent.summary` is written by the service layer and is authoritative;
 * these helpers only supply the verb chip and the day grouping the feed and the
 * per-issue panel both render, so the two views never disagree about what a
 * day boundary is.
 */
import type { ActivityAction, ActivityEvent, ActivityGroup } from "@/types/activity";

export const ACTIVITY_LABELS: Readonly<Record<ActivityAction, string>> = {
  "organization.updated": "updated the organization",
  "project.created": "created a project",
  "project.updated": "updated a project",
  "project.archived": "archived a project",
  "project.restored": "restored a project",
  "issue.created": "created an issue",
  "issue.updated": "updated an issue",
  "issue.status_changed": "changed status",
  "issue.assigned": "assigned an issue",
  "issue.archived": "archived an issue",
  "issue.restored": "restored an issue",
  "comment.created": "commented",
  "comment.updated": "edited a comment",
  "comment.deleted": "deleted a comment",
  "member.invited": "invited a member",
  "member.joined": "joined the organization",
  "member.role_changed": "changed a role",
  "member.removed": "removed a member",
  "billing.plan_changed": "changed the plan",
  "flag.toggled": "toggled a feature flag",
};

export function activityLabel(action: ActivityAction): string {
  return ACTIVITY_LABELS[action] ?? action;
}

/** The calendar day an event belongs to, in UTC (`YYYY-MM-DD`). */
export function activityDay(event: ActivityEvent): string {
  return event.occurredAt.slice(0, 10);

