/**
 * Billing-period arithmetic: where a period ends, what a full period costs and
 * how much of it is left after a mid-period change.
 *
 * All calendar maths is done in UTC. A monthly period ends on the same day of
 * the following month (clamped to that month's last day), an annual period on
 * the same day and month of the following year (29 February → 28 February).
 * Each period is computed from its own start, so a clamped day carries forward.
 */
import { getPlanLimits } from "@/config/plan-limits";
import type { BillingInterval, PlanId } from "@/types/billing";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Months covered by one period of the given interval. */
export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

function daysInMonthUtc(year: number, month: number): number {
  return new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
}

/** The end of a period of `interval` that starts at `start`. */
export function addBillingInterval(
  start: Date,
  interval: BillingInterval,
): Date {
  const months = monthsInInterval(interval);
