    .update(subscriptions)
    .set({
      plan: "free",
      interval: "monthly",
      status: "active",
      cancelAt: null,
      currentPeriodStart: period.start,
      currentPeriodEnd: period.end,
      updatedAt: toIsoTimestamp(new Date()),
