/**
 * Feeds the renewal job: the subscription of every organization that has not
 * been deleted. Cross-tenant by design, it sweeps every org.
 */
export async function listSubscriptionsOfLiveOrgs(): Promise<
  readonly Subscription[]
> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(isNull(organizations.archivedAt))
    .all();

  return rows.map((row) => toSubscription(row.subscription));
}

/**
 * Moves an active subscription on to `next`, and writes its invoice in the
 * same transaction when `invoiceAmountCents` is given. Only applies while the
 * row still holds the period `current` ended with, so a replay (or a second
 * runner) that read the same row changes nothing and gets `null`.
 */
export async function advancePeriod(
  current: Subscription,
  next: BillingPeriod,
  invoiceAmountCents: number | null,
): Promise<{ subscription: Subscription; invoice: Invoice | null } | null> {
  const orgId = current.orgId;

  return getDb().transaction((tx) => {
    const row = tx
      .update(subscriptions)
      .set({
        currentPeriodStart: next.start,
        currentPeriodEnd: next.end,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(
        and(
          orgPredicate(subscriptions.orgId, orgId),
          eq(subscriptions.status, "active"),
          eq(subscriptions.plan, current.plan),
          eq(subscriptions.currentPeriodEnd, current.currentPeriodEnd),
        ),
      )
      .returning()
      .get();

    if (!row) return null;

    const invoice =
      invoiceAmountCents === null
        ? null
        : issueInvoiceWith(tx, orgId, {
            amountCents: invoiceAmountCents,
            periodStart: next.start,
            periodEnd: next.end,
          });

    return { subscription: toSubscription(row), invoice };
  });
}

/**
 * Ends a cancelled subscription: the org lands on an active free plan with a
 * monthly period starting at `period.start`. Conditional on the cancellation
 * still being the one `current` carried, so a replay is a no-op (`null`).
 */
export async function endCanceledSubscription(
  current: Subscription,
  period: BillingPeriod,
): Promise<Subscription | null> {
  if (current.cancelAt === null) return null;

  const row = getDb()
    .update(subscriptions)
    .set({
      plan: "free",
      interval: "monthly",
      status: "active",
      cancelAt: null,
      currentPeriodStart: period.start,
      currentPeriodEnd: period.end,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(subscriptions.orgId, current.orgId),
        eq(subscriptions.status, "canceled"),
        eq(subscriptions.cancelAt, current.cancelAt),
      ),
    )
    .returning()
    .get();

  return row ? toSubscription(row) : null;
}
'''
open(p,'w').write(s)
EOF

