import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import { addBillingInterval, prorateCents } from "@/lib/billing-period";
import { getDb, subscriptions } from "@/server/db";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import * as billingService from "@/server/services/billing-service";
import { registerActivityListeners, listActivity } from "@/server/services/activity-service";
import { listNotifications } from "@/server/services/notification-service";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import { eq } from "drizzle-orm";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerActivityListeners(); });
afterAll(() => cleanup());

function setSub(orgId: string, patch: Record<string, unknown>) {
  getDb().update(subscriptions).set(patch).where(eq(subscriptions.orgId, orgId)).run();
}

describe("periods", () => {
  it("clamps", () => {
    const d = (s: string) => addBillingInterval(new Date(s), "monthly").toISOString();
    expect(d("2026-01-31T10:00:00.000Z")).toBe("2026-02-28T10:00:00.000Z");
    expect(d("2026-02-28T10:00:00.000Z")).toBe("2026-03-28T10:00:00.000Z");
    expect(d("2026-12-15T10:00:00.000Z")).toBe("2027-01-15T10:00:00.000Z");
    expect(addBillingInterval(new Date("2028-02-29T00:00:00.000Z"), "annual").toISOString()).toBe("2029-02-28T00:00:00.000Z");
    expect(prorateCents(3000, new Date("2026-03-01T00:00:00Z"), new Date("2026-03-31T00:00:00Z"), new Date("2026-03-16T02:00:00Z"))).toBe(1500);
  });
});

describe("job", () => {
  it("renews 3 months", async () => {
    const t = await createTenant("renew", "starter");
    setSub(t.org.id, { status: "active", seats: 2, currentPeriodStart: "2026-01-31T09:00:00.000Z", currentPeriodEnd: "2026-02-28T09:00:00.000Z" });
    const seen: unknown[] = [];
    const off = subscribe("billing.invoice_issued", (p) => { seen.push(p); });
    const now = new Date("2026-05-01T00:00:00.000Z");
    const r = await runBillingRenewalJob(now);
    const r2 = await runBillingRenewalJob(now);
    off();
    const sub = await subscriptionRepo.findSubscription(t.org.id);
    console.log(r, r2, sub, seen);
    const inv = await billingService.listInvoices(t.actors.owner, t.org.id);
    console.log(inv);
    expect(inv).toHaveLength(3);
    const notes = await listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: t.userIds.owner, unreadOnly: false, limit: 50, cursor: null } as never);
    console.log(notes.items.map((n) => [n.kind, n.title]));
    const act = await listActivity(t.actors.owner, { orgId: t.org.id, limit: 50, cursor: null } as never);
    console.log(act.items.map((a) => [a.action, a.summary, a.subjectKind, a.subjectId]));
  });

  it("cancels", async () => {
    const t = await createTenant("cancel", "growth");
    setSub(t.org.id, { status: "canceled", cancelAt: "2026-03-10T00:00:00.000Z", currentPeriodStart: "2026-02-10T00:00:00.000Z", currentPeriodEnd: "2026-03-10T00:00:00.000Z" });
    const seen: unknown[] = [];
    const off = subscribe("billing.plan_changed", (p) => { seen.push(p); });
    await runBillingRenewalJob(new Date("2026-03-09T00:00:00.000Z"));
    expect(seen).toHaveLength(0);
    await runBillingRenewalJob(new Date("2026-05-20T00:00:00.000Z"));
    await runBillingRenewalJob(new Date("2026-05-20T00:00:00.000Z"));
    off();
    console.log(seen, await subscriptionRepo.findSubscription(t.org.id));
    expect(seen).toHaveLength(1);
  });

  it("skips archived orgs", async () => {
    const t = await createTenant("archived", "growth");
